function parseSTL8(buf){let dv=new DataView(buf),v=[];if(buf.byteLength>=84&&84+50*dv.getUint32(80,true)===buf.byteLength){let n=dv.getUint32(80,true);if(n>30000)throw Error('Limit 30,000 STL triangles');for(let i=0;i<n;i++)for(let j=0;j<9;j++)v.push(dv.getFloat32(84+i*50+12+j*4,true))}else{let txt=new TextDecoder().decode(buf),rx=/\bvertex\s+([+-]?[\d.]+(?:e[+-]?\d+)?)\s+([+-]?[\d.]+(?:e[+-]?\d+)?)\s+([+-]?[\d.]+(?:e[+-]?\d+)?)/gi;for(let m of txt.matchAll(rx)){v.push(+m[1],+m[2],+m[3]);if(v.length>270000)throw Error('Limit 30,000 STL triangles')}}if(v.length<9||v.length%9||!v.every(Number.isFinite))throw Error('Invalid STL vertices');let lo=[Infinity,Infinity,Infinity],hi=[-Infinity,-Infinity,-Infinity];for(let i=0;i<v.length;i++){let j=i%3;lo[j]=Math.min(lo[j],v[i]);hi[j]=Math.max(hi[j],v[i])}let size=hi.map((n,i)=>n-lo[i]);if(size.some(n=>n>50000)||!size.some(n=>n>0))throw Error('STL envelope invalid or too large in mm');let origin=[(lo[0]+hi[0])/2,lo[1],(lo[2]+hi[2])/2];return {verts:v.map((n,i)=>n-origin[i%3]),size}}
